  Definition full_table : list (list Pallas.point) :=
    FixedBaseTableDefs.nonlast_points 84 G
    ++ [FixedBaseTableDefs.last_row (FixedBaseTableDefs.base_pow8 84 G) (Pallas.mul (FixedBaseTableDefs.window_offset_sum 84) G)].

